SELECT hpdp.*
FROM hls_product_definition_para hpdp
WHERE hpdp.definition_id = #{definitionId} and hpdp.product_para = #{productPara}

SELECT nvl(hpdp.default_value,0) default_value
FROM hls_product_definition_para hpdp
WHERE hpdp.definition_id = #{definitionId} and hpdp.product_para = #{productPara}
